begin;
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002');
insert into businesses(id,owner_id,name) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Costing fixture');
insert into business_members(business_id,user_id,role) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','owner');
insert into customers(id,business_id,name,phone) values ('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Fixture','2025550100');
insert into business_members(business_id,user_id,role) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002','staff');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
do $$
declare j jobs; c crew_members; inv invoices; t time_entries; p uuid:=gen_random_uuid(); r uuid:=gen_random_uuid(); stamp timestamptz:=now(); bid uuid:='20000000-0000-4000-8000-000000000001';
begin
 insert into jobs(business_id,customer_id,title,price,status) values(bid,'30000000-0000-4000-8000-000000000001','Job',100,'draft') returning * into j;
 insert into crew_members(business_id,name,pay_type,pay_rate) values(bid,'Employee','hourly',24) returning * into c;
 insert into time_entries(business_id,job_id,crew_member_id,clocked_in_at,clocked_out_at,labor_hourly_rate) values(bid,j.id,c.id,now()-interval '2 hours',now()-interval '1 hour',999) returning * into t;
 if t.labor_hourly_rate<>24 then raise exception 'Client rate accepted'; end if;
 update crew_members set pay_rate=30 where id=c.id;
 update time_entries set labor_hourly_rate=999 where id=t.id;
 if (select labor_hourly_rate from time_entries where id=t.id)<>24 then raise exception 'Historic rate changed'; end if;
 begin insert into time_entries(business_id,job_id,crew_member_id,clocked_in_at,clocked_out_at) values(bid,j.id,c.id,now()-interval '90 minutes',now()-interval '30 minutes'); raise exception 'Overlap accepted'; exception when check_violation then null; end;
 insert into time_entries(business_id,job_id,crew_member_id,clocked_in_at,clocked_out_at) values(bid,j.id,c.id,now()-interval '1 hour',now()) returning * into t;
 perform record_job_time(j.id,c.id,'90000000-0000-4000-8000-000000000001',now()-interval '4 hours',now()-interval '3 hours');
 perform record_job_time(j.id,c.id,'90000000-0000-4000-8000-000000000001',now()-interval '4 hours',now()-interval '3 hours');
 if (select count(*) from time_entries where id='90000000-0000-4000-8000-000000000001')<>1 then raise exception 'Time retry duplicated'; end if;
 if t.labor_hourly_rate<>30 then raise exception 'New rate missing'; end if;
 begin insert into time_entries(business_id,job_id,crew_member_id,clocked_in_at,clocked_out_at) values(bid,j.id,c.id,now(),now()+interval '1 hour'); raise exception 'Future accepted'; exception when check_violation then null; end;
 select * into inv from convert_job_to_invoice(j.id);
 perform record_invoice_payment(inv.id,p,100,'cash');
 perform record_invoice_refund(inv.id,p,r,25,'cash','Returned for service credit',stamp);
 perform record_invoice_refund(inv.id,p,r,25,'cash','Returned for service credit',stamp);
 select * into inv from invoices where id=inv.id;
 if inv.refunded_total<>25 or inv.paid_total<>100 or inv.status<>'paid' then raise exception 'Refund incorrectly reopened debt or duplicated'; end if;
 if (get_customer_document('invoice',inv.id)->>'refunded_total')::numeric<>25 then raise exception 'Document refund absent'; end if;
 if (get_portal_data('30000000-0000-4000-8000-000000000001')->'invoices'->0->>'refunded_total')::numeric<>25 then raise exception 'Portal refund absent'; end if;
 begin perform record_invoice_refund(inv.id,p,r,26,'cash','Changed',stamp); raise exception 'Changed retry accepted'; exception when check_violation then null; end;
 begin perform record_invoice_refund(inv.id,p,gen_random_uuid(),76,'cash','Too much',stamp); raise exception 'Over-refund accepted'; exception when check_violation then null; end;
 begin perform record_invoice_refund(inv.id,p,gen_random_uuid(),1.001,'cash','Precision',stamp); raise exception 'Precision accepted'; exception when invalid_parameter_value then null; end;
 begin perform record_invoice_refund(inv.id,p,gen_random_uuid(),1,'cash','Future',stamp+interval '1 day'); raise exception 'Future refund accepted'; exception when invalid_parameter_value then null; end;
 begin perform record_invoice_refund(inv.id,p,gen_random_uuid(),1,'cash','',stamp); raise exception 'Blank accepted'; exception when check_violation then null; end;
 begin delete from invoice_refunds where id=r; raise exception 'Delete accepted'; exception when insufficient_privilege then null; end;
 begin update invoice_refunds set amount=1 where id=r; raise exception 'Edit accepted'; exception when insufficient_privilege then null; end;
 update invoices set refunded_total=999 where id=inv.id;
 if (select refunded_total from invoices where id=inv.id)<>25 then raise exception 'Refund cache trusted'; end if;
 perform record_invoice_refund(inv.id,p,gen_random_uuid(),75,'cash','Remaining credit',stamp);
 if (select refunded_total from invoices where id=inv.id)<>100 then raise exception 'Full refund failed'; end if;
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
 if not exists(select 1 from invoice_refunds where id=r) then raise exception 'Office history hidden'; end if;
 begin perform record_invoice_refund(inv.id,p,gen_random_uuid(),1,'cash','Staff',stamp); raise exception 'Non-owner refund accepted'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
 if exists(select 1 from invoice_refunds where id=r) then raise exception 'Foreign refunds exposed'; end if;
 begin perform record_invoice_refund(inv.id,p,gen_random_uuid(),1,'cash','Foreign',stamp); raise exception 'Foreign write accepted'; exception when insufficient_privilege then null; end;
 if has_table_privilege('anon','invoice_refunds','select') or has_function_privilege('anon','record_invoice_refund(uuid,uuid,uuid,numeric,text,text,timestamptz)','execute') then raise exception 'Anonymous access'; end if;
end $$;
rollback;
